import sys
from collections import Counter


def main():
    data = sys.stdin.read().split()
    n, s = int(data[0]), int(data[1])
    cnt = Counter(int(x) for x in data[2:2 + n])
    res = []
    for a in sorted(cnt):
        b = s - a
        if a < b:
            if b in cnt:
                res.append((a, b))
        elif a == b:
            if cnt[a] >= 2:
                res.append((a, b))
        else:
            break
    out = [str(len(res))]
    out.extend('%d %d' % p for p in res)
    print('\n'.join(out))


